<script>
(()=>{const form=document.querySelector('#footerStudioForm'),preview=document.querySelector('[data-footer-preview]');if(!form||!preview)return;
 const map={footer_background:'--p-bg',footer_text_color:'--p-text',footer_heading_color:'--p-heading',footer_accent_color:'--p-accent',footer_button_background:'--p-btn',footer_button_text:'--p-btn-text',footer_border_color:'--p-border',footer_padding_top:'--p-top',footer_padding_bottom:'--p-bottom',footer_column_gap:'--p-gap',footer_logo_height:'--p-logo',footer_social_size:'--p-social',footer_heading_size:'--p-heading-size',footer_text_size:'--p-text-size',footer_element_radius:'--p-radius'};
 const sync=()=>{Object.entries(map).forEach(([name,css])=>{const el=form.elements[name];if(!el)return;let value=el.value;if(el.type==='range')value+='px';preview.style.setProperty(css,value)});const layout=form.querySelector('[name="footer_layout"]:checked')?.value||'balanced';preview.className='footer-demo layout-'+layout;
  const bind={logo:'[data-preview-logo]',description:'[data-preview-description]','menu-title':'[data-preview-menu-title]','categories-title':'[data-preview-categories-title]','cta-title':'[data-preview-cta-title]','cta-text':'[data-preview-cta-text]','cta-label':'[data-preview-cta]'};form.querySelectorAll('[data-preview-input]').forEach(el=>{const k=el.dataset.previewInput,target=bind[k]?preview.querySelector(bind[k]):null;if(target)target.textContent=el.value||''});
  const copyright=form.elements.footer_copyright?.value?.trim()||'© '+new Date().getFullYear()+' سراديب';preview.querySelector('[data-preview-copyright]').textContent=copyright;const dp=form.elements.footer_designer_prefix_ar?.value?.trim()||'',dn=form.elements.footer_designer_name?.value?.trim()||'';preview.querySelector('[data-preview-designer]').textContent=dp+(dp&&dn?' ':'')+dn;
  form.querySelectorAll('.footer-color').forEach(w=>{const c=w.querySelector('input[type="color"]'),t=w.querySelector('[data-color-text]');if(c&&t)t.value=c.value.toUpperCase()});form.querySelectorAll('.footer-range').forEach(w=>{const i=w.querySelector('input[type="range"]'),o=w.querySelector('output');if(i&&o)o.textContent=i.value+'px'});
 };
 form.addEventListener('input',sync);form.addEventListener('change',sync);sync();})();
</script>
